import * as THREE from 'three';

const BOTTOM_COLOR = [0.1, 0.9, 0.5];
const TOP_COLOR = [0.5, 0.2, 0.9];
const AMP = 1.2;

export function buildAurora({ length = 30, height = 6, segsX = 120, segsY = 12 } = {}) {
  const geometry = new THREE.PlaneGeometry(length, height, segsX, segsY);
  const position = geometry.attributes.position;
  const count = position.count;
  const colors = new Float32Array(count * 3);
  const halfHeight = height / 2;
  const dr = TOP_COLOR[0] - BOTTOM_COLOR[0];
  const dg = TOP_COLOR[1] - BOTTOM_COLOR[1];
  const db = TOP_COLOR[2] - BOTTOM_COLOR[2];

  for (let i = 0; i < count; i++) {
    // v in [0, 1], bottom edge to top edge
    const v = (position.getY(i) + halfHeight) / height;
    colors[i * 3 + 0] = BOTTOM_COLOR[0] + dr * v;
    colors[i * 3 + 1] = BOTTOM_COLOR[1] + dg * v;
    colors[i * 3 + 2] = BOTTOM_COLOR[2] + db * v;
  }

  geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

  const material = new THREE.MeshBasicMaterial({
    vertexColors: true,
    side: THREE.DoubleSide,
    transparent: true,
  });

  const mesh = new THREE.Mesh(geometry, material);

  // Cache original positions for wave displacement
  mesh.userData.originalPositions = Float32Array.from(position.array);
  mesh.userData.height = height;

  return mesh;
}

export function updateAurora(mesh, t) {
  const { originalPositions, height } = mesh.userData;
  const position = mesh.geometry.attributes.position;
  const array = position.array;
  const halfHeight = height / 2;

  for (let i = 0; i < position.count; i++) {
    const x = originalPositions[i * 3 + 0];
    const y = originalPositions[i * 3 + 1];
    array[i * 3 + 2] =
      AMP * Math.sin(0.35 * x + 1.1 * t) * ((y + halfHeight) / height + 0.5);
  }

  position.needsUpdate = true;
}

