import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildAurora, updateAurora } from '../src/aurora.js';

const BOTTOM = [0.1, 0.9, 0.5];
const TOP = [0.5, 0.2, 0.9];

describe('buildAurora', () => {
  const mesh = buildAurora();
  const geom = mesh.geometry;
  const pos = geom.attributes.position;
  const col = geom.attributes.color;
  const height = mesh.userData.height;

  it('has a color attribute with itemSize 3', () => {
    expect(col).toBeInstanceOf(THREE.BufferAttribute);
    expect(col.itemSize).toBe(3);
    expect(col.count).toBe(pos.count);
  });

  // Group vertex indices by row (unique y values)
  const rows = new Map();
  for (let i = 0; i < pos.count; i++) {
    const y = pos.getY(i);
    if (!rows.has(y)) rows.set(y, []);
    rows.get(y).push(i);
  }
  const ys = [...rows.keys()].sort((a, b) => a - b);
  const bottomRow = rows.get(ys[0]);
  const topRow = rows.get(ys[ys.length - 1]);
  const midRow = rows.get(ys[Math.floor(ys.length / 2)]);
  const midY = ys[Math.floor(ys.length / 2)];

  it('bottom-row vertices equal the bottom color within 1e-6', () => {
    for (const i of bottomRow) {
      expect(col.getX(i)).toBeCloseTo(BOTTOM[0], 6);
      expect(col.getY(i)).toBeCloseTo(BOTTOM[1], 6);
      expect(col.getZ(i)).toBeCloseTo(BOTTOM[2], 6);
    }
  });

  it('top-row vertices equal the top color within 1e-6', () => {
    for (const i of topRow) {
      expect(col.getX(i)).toBeCloseTo(TOP[0], 6);
      expect(col.getY(i)).toBeCloseTo(TOP[1], 6);
      expect(col.getZ(i)).toBeCloseTo(TOP[2], 6);
    }
  });

  it('mid-row colors are the exact average of bottom and top', () => {
    for (const i of midRow) {
      expect(col.getX(i)).toBe((BOTTOM[0] + TOP[0]) / 2);
      expect(col.getY(i)).toBe((BOTTOM[1] + TOP[1]) / 2);
      expect(col.getZ(i)).toBe((BOTTOM[2] + TOP[2]) / 2);
    }
  });

  it('colors blend linearly in v across all vertices', () => {
    const halfH = height / 2;
    for (let i = 0; i < pos.count; i++) {
      const v = (pos.getY(i) + halfH) / height;
      expect(col.getX(i)).toBeCloseTo(BOTTOM[0] + (TOP[0] - BOTTOM[0]) * v, 12);
      expect(col.getY(i)).toBeCloseTo(BOTTOM[1] + (TOP[1] - BOTTOM[1]) * v, 12);
      expect(col.getZ(i)).toBeCloseTo(BOTTOM[2] + (TOP[2] - BOTTOM[2]) * v, 12);
    }
  });
});

describe('updateAurora', () => {
  const mesh = buildAurora();

  function displacementFactor(y, h) {
    return (y + h / 2) / h + 0.5; // normalized y/height in [0,1]
  }

  it('five sampled vertices match the displacement formula within 1e-9 at t=2', () => {
    updateAurora(mesh, 2);
    const pos = mesh.geometry.attributes.position;
    const orig = mesh.userData.originalPositions;
    const height = mesh.userData.height;
    const n = pos.count;
    const samples = [0, Math.floor(n / 4), Math.floor(n / 2), Math.floor((3 * n) / 4), n - 1];
    for (const i of samples) {
      const x = orig[i * 3];
      const y = orig[i * 3 + 1];
      const expected = 1.2 * Math.sin(0.35 * x + 1.1 * 2) * displacementFactor(y, height);
      expect(Math.abs(pos.getZ(i) - expected)).toBeLessThanOrEqual(1e-9);
    }
  });

  it('only displaces z; x and y stay at their cached originals', () => {
    updateAurora(mesh, 2);
    const pos = mesh.geometry.attributes.position;
    const orig = mesh.userData.originalPositions;
    for (let i = 0; i < pos.count; i++) {
      expect(pos.getX(i)).toBe(orig[i * 3]);
      expect(pos.getY(i)).toBe(orig[i * 3 + 1]);
    }
  });

  it('two calls with equal t are idempotent', () => {
    updateAurora(mesh, 3.7);
    const a = Float32Array.from(mesh.geometry.attributes.position.array);
    updateAurora(mesh, 3.7);
    const b = Float32Array.from(mesh.geometry.attributes.position.array);
    expect(b).toEqual(a);
  });

  it('z displacement magnitude never exceeds 1.2*1.5', () => {
    for (const t of [0, 1.234, 2, 5.67, 100]) {
      updateAurora(mesh, t);
      const pos = mesh.geometry.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        expect(Math.abs(pos.getZ(i))).toBeLessThanOrEqual(1.2 * 1.5 + 1e-12);
      }
    }
  });
});

